const modules = [
  {
    id: "0.1",
    title: "OK3YO AI Auditor",
    subtitle: "Automate operations, from factory floor to M&V reporting.",
    desc: "Advanced neural agents inspecting HVAC motor specifications, fan CFM analysis, and VFD speed logic.",
  },
  {
    id: "0.2",
    title: "ConEd & Willdan Ledger",
    subtitle: "Achieve energy audit superiority, from baseline to post-inspection.",
    desc: "Rigorous measurement & verification data pipelines built for institutional efficiency incentive compliance.",
  },
  {
    id: "0.3",
    title: "Abstract Portal",
    subtitle: "Build and manage ontology-powered energy software.",
    desc: "Complete developer platform for real-time telemetry and commercial property tracking.",
  },
];

export default function Modules() {
  return (
    <section className="px-8 py-24 max-w-7xl mx-auto">
      <div className="mb-16">
        <span className="font-mono text-xs text-zinc-500 tracking-widest uppercase">// PLATFORM ARCHITECTURE</span>
        <h2 className="text-3xl md:text-4xl font-light tracking-tight text-white mt-2">
          Engineered for Industrial Scale
        </h2>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {modules.map((mod) => (
          <div 
            key={mod.id}
            className="group relative bg-obsidian-card border border-obsidian-border p-8 hover:border-zinc-500 transition-all duration-300 flex flex-col justify-between min-h-[320px]"
          >
            <div>
              <div className="flex items-center justify-between mb-8 font-mono text-xs text-zinc-500">
                <span>/{mod.id}</span>
                <span className="w-1.5 h-1.5 bg-zinc-600 group-hover:bg-palantir-accent transition-colors" />
              </div>
              <h3 className="text-xl font-medium text-white mb-3 group-hover:text-palantir-accent transition-colors">
                {mod.title}
              </h3>
              <p className="text-sm text-zinc-300 mb-4 font-light">
                {mod.subtitle}
              </p>
              <p className="text-xs text-zinc-500 font-mono leading-relaxed">
                {mod.desc}
              </p>
            </div>
            <div className="mt-8 pt-4 border-t border-obsidian-border flex items-center justify-between font-mono text-xs text-zinc-400 group-hover:text-white transition-colors cursor-pointer">
              <span>EXPLORE MODULE</span>
              <span>→</span>
            </div>
          </div>
        ))}
      </div>
    </section>
  );
}